31	// CustomerRecord is one customer to import, read from a line of an import file.
32	type CustomerRecord struct {
33		Row                  int // the line where the record starts, in the file
34		Name                 string
35		Email                string
36		DefaultPaymentMethod string
37		Metadata             map[string]string
38	}
