40	// RowProblem says why a record of an import is refused: its first problem, as an error code.
41	type RowProblem struct {
42		Row   int    `json:"row"`
43		Error string `json:"error"`
44	}
45	
46	// ImportCustomers creates a customer for each record, in order, or for none: when any record has a problem it creates
47	// nothing and returns every problem in file order. The checks are those of CreateCustomer, and an email address may not
48	// repeat an earlier record's. With dryRun it only checks. The whole import happens under one lock.
49	func (s *Store) ImportCustomers(orgID string, recs []CustomerRecord, now time.Time, dryRun bool) ([]Customer, []RowProblem, error) {
50		s.mu.Lock()
51		defer s.mu.Unlock()
52		if _, ok := s.orgs[orgID]; !ok {
53			return nil, nil, ErrNotFound
54		}
55		// The global email index holds one customer per address across all organizations, so it cannot say whether this
56		// organization has the address too. Collect this organization's own addresses instead.
57		taken := map[string]bool{}
58		for _, c := range s.customers {
59			if c.OrgID == orgID {
60				taken[normEmail(c.Email)] = true
61			}
62		}
63		var problems []RowProblem
64		seen := map[string]bool{}
65		for _, rec := range recs {
66			name, email := strings.TrimSpace(rec.Name), strings.TrimSpace(rec.Email)
67			key := normEmail(email)
68			code := ""
69			switch {
70			case name == "":
71				code = "missing_name"
72			case !validEmail(email):
73				code = "invalid_email"
74			case rec.DefaultPaymentMethod != "" && !strings.HasPrefix(rec.DefaultPaymentMethod, "pm_"):
75				code = "invalid_payment_method"
76			case taken[key]:
77				code = "email_taken"
78			case seen[key]:
79				code = "duplicate_email"
80			}
81			seen[key] = true
82			if code != "" {
83				problems = append(problems, RowProblem{Row: rec.Row, Error: code})
84			}
85		}
86		if len(problems) > 0 || dryRun {
87			return nil, problems, nil
88		}
89		out := make([]Customer, 0, len(recs))
90		for _, rec := range recs {
91			c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(rec.Name), Email: strings.TrimSpace(rec.Email),
92				DefaultPaymentMethod: rec.DefaultPaymentMethod, Metadata: rec.Metadata, CreatedAt: now.UTC()}
93			s.customers[c.ID] = c
94			s.customersByEmail[normEmail(c.Email)] = c.ID
95			out = append(out, copyCustomer(c))
96		}
97		return out, nil, nil
98	}
99	
100	// Customer returns one of an organization's customers.
101	func (s *Store) Customer(orgID, id string) (Customer, bool) {
102		s.mu.Lock()
103		defer s.mu.Unlock()
104		c, ok := s.customers[id]
105		if !ok || c.OrgID != orgID {
106			return Customer{}, false
107		}
108		return copyCustomer(c), true
109	}
